suppressPackageStartupMessages({library(readr); library(dplyr); library(stringr); library(tidyr)})
root_dir <- normalizePath(file.path(getwd()), winslash = "/", mustWork = TRUE)
infile <- file.path(root_dir, "data/raw/analysis_ready_model_dataset_before_deduplication.csv")
if (!file.exists(infile)) stop("Missing canonical input: ", infile)
d <- read_csv(guess_max=100000, infile, show_col_types = FALSE)
key <- c("StudyID","SpeciesID","ObservedStage","StressorLabel","Metric","TransformedMetric","Category","lnRR","Variance")
missing <- setdiff(key, names(d)); if (length(missing)) stop("Missing duplicate key columns: ", paste(missing, collapse=", "))
norm <- function(x) {x <- str_squish(as.character(x)); x[is.na(x)] <- "<NA>"; x}
for (nm in key) d[[paste0(".key_",nm)]] <- norm(d[[nm]])
d$.duplicate_group <- do.call(paste, c(d[paste0(".key_",key)], sep = " || "))
counts <- d %>% count(.duplicate_group, name="DuplicateGroupSize")
d <- d %>% left_join(counts, by=".duplicate_group") %>% group_by(.duplicate_group) %>% mutate(DuplicateCandidateGroup=if_else(DuplicateGroupSize>1,.duplicate_group,NA_character_), DuplicateReason=if_else(DuplicateGroupSize>1,"Exact cross-layer duplicate: identical analysis key and effect values",NA_character_), ValueConflict=length(unique(paste(format(lnRR,digits=16),format(Variance,digits=16))))>1, .priority=case_when(UpdateLayer=="Original curated evidence"~1L, UpdateLayer=="Earlier validated expansion"~2L, TRUE~3L), KeepEffect=seq_along(.priority)==match(min(.priority),.priority)) %>% ungroup()
conflicts <- d %>% filter(DuplicateGroupSize>1, ValueConflict)
if (nrow(conflicts)) stop("Conflicting duplicate groups require manual review: ", nrow(conflicts))
audit <- d %>% group_by(.duplicate_group) %>% mutate(RetainedForAnalysis=KeepEffect, RetainedRowID=if_else(any(KeepEffect),LatestModelRowID[which(KeepEffect)[1]],NA_integer_), DeletedRowID=if_else(!KeepEffect,LatestModelRowID,NA_integer_), RetainedUpdateLayer=if_else(any(KeepEffect),UpdateLayer[which(KeepEffect)[1]],NA_character_), DeletedUpdateLayer=if_else(!KeepEffect,UpdateLayer,NA_character_)) %>% ungroup() %>% select(LatestModelRowID,RowKey,StudyID,SpeciesID,ObservedStage,StressorLabel,Metric,TransformedMetric,Category,lnRR,Variance,UpdateLayer,SourceDataset,DuplicateCandidateGroup,DuplicateReason,ValueConflict,RetainedForAnalysis,RetainedRowID,DeletedRowID,RetainedUpdateLayer,DeletedUpdateLayer)
dir.create(file.path(root_dir,"data/source_data"), recursive=TRUE, showWarnings=FALSE); dir.create(file.path(root_dir,"data/processed"), recursive=TRUE, showWarnings=FALSE)
write_csv(audit,file.path(root_dir,"data/source_data/Review_duplicate_resolution_audit.csv"),na="")
write_csv(conflicts,file.path(root_dir,"data/source_data/Review_duplicate_conflicts.csv"),na="")
canonical <- d %>% filter(KeepEffect) %>% select(-starts_with('.key_'),-.duplicate_group,-DuplicateGroupSize,-ValueConflict,-.priority,-KeepEffect)
write_csv(canonical,file.path(root_dir,"data/processed/analysis_ready_model_dataset_deduplicated.csv"),na="")
write_csv(canonical,file.path(root_dir,"data/processed/analysis_ready_model_dataset.csv"),na="")
summary <- bind_rows(tibble(Scope="Full database",InputRows=nrow(d),RetainedRows=nrow(canonical),DeletedRows=sum(!d$KeepEffect),StudyIDs=n_distinct(canonical$StudyID)), tibble(Scope="Primary metamorphic subset",InputRows=sum(d$DevelopmentalModeGroup=="With metamorphic stage",na.rm=TRUE),RetainedRows=sum(canonical$DevelopmentalModeGroup=="With metamorphic stage",na.rm=TRUE),DeletedRows=sum(d$DevelopmentalModeGroup=="With metamorphic stage" & !d$KeepEffect,na.rm=TRUE),StudyIDs=n_distinct(canonical$StudyID[canonical$DevelopmentalModeGroup=="With metamorphic stage"])))
write_csv(summary,file.path(root_dir,"data/processed/duplicate_resolution_summary.csv"),na="")
writeLines(c("Duplicate resolution rule: exact groups defined by StudyID, SpeciesID, ObservedStage, StressorLabel, Metric, TransformedMetric, Category, lnRR and Variance.","Original curated evidence is retained over Earlier validated expansion when all values agree.","Conflicting groups are not auto-resolved."),file.path(root_dir,"data/source_data/Review_duplicate_resolution_rule.txt"))
print(summary)
